const fs = require('fs');
const path = require('path');

const sender = 'ethan.it.specialist';
const recipient = 'olivia.hr.manager';
const subject = 'Re: High Priority: Onboarding Equipment Setup Needed';
const content = \`Hello Olivia,

Thank you for your onboarding request. I wanted to confirm that I have received it and the equipment setup for the new contractor is now scheduled.

Here is a summary of what will be completed before start of business tomorrow (Monday, September 21):

1. Standard Windows laptop — configured and ready
2. VPN access — provisioned and tested
3. Email account — set up and active

I have created a tracking event on my calendar for tomorrow morning at 8:00 AM to ensure everything is finalized on time. Please rest assured this is being treated as a high priority.

If there are any additional requirements or details about the contractor, please let me know.

Best regards,
Ethan\`;

const email = [
  'From: ' + sender + '@company.com',
  'To: ' + recipient + '@company.com',
  'Subject: ' + subject,
  'Content-Type: text/plain; charset=\"utf-8\"',
  'Content-Transfer-Encoding: 7bit',
  'MIME-Version: 1.0',
  '',
  content
].join('\n');

// Save to both sender and recipient folders
for (const folder of [sender, recipient]) {
  const dir = path.join('/workspace/testbed/emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  const filePath = path.join(dir, subject + '.eml');
  fs.writeFileSync(filePath, email);
  console.log('Saved to: ' + filePath);
}

console.log('\nEmail sent successfully.');
"
